package dev.boxlet.shared.brand

import kotlin.math.cos
import kotlin.math.sin

// Generated by scripts/generate_brand_assets.py from design/brand/parcel.json.
// Coordinates are dimensionless; all faces use the same dimetric projection.
object ParcelGeometry {
    data class Point(val x: Float, val y: Float)
    const val TopColor: Long = 0xFFC3DFF3
    const val TopShadeColor: Long = 0xFFABCFEA
    const val LeftColor: Long = 0xFF8BB9DE
    const val LeftShadeColor: Long = 0xFF76A9D2
    const val RightColor: Long = 0xFF6094C0
    const val RightShadeColor: Long = 0xFF487EAC
    const val InteriorColor: Long = 0xFF416D94
    const val TapeColor: Long = 0xFFF4F8FC
    const val EdgeColor: Long = 0xFF497DA9
    const val BackgroundColor: Long = 0xFFFAFCFF
    /** Icon surfaces draw the mark centred and inset, matching the exported launcher art. */
    const val IconScale: Float = 0.76f
    val IconCenter = Point(0.500000f, 0.530000f)
    val left = listOf(Point(0.200000f, 0.370000f), Point(0.500000f, 0.520000f), Point(0.500000f, 0.840000f), Point(0.200000f, 0.690000f))
    val right = listOf(Point(0.500000f, 0.520000f), Point(0.800000f, 0.370000f), Point(0.800000f, 0.690000f), Point(0.500000f, 0.840000f))
    val interior = listOf(Point(0.500000f, 0.220000f), Point(0.800000f, 0.370000f), Point(0.500000f, 0.520000f), Point(0.200000f, 0.370000f))
    val topTape = listOf(Point(0.624500f, 0.282250f), Point(0.675500f, 0.307750f), Point(0.375500f, 0.457750f), Point(0.324500f, 0.432250f))
    val frontTape = listOf(Point(0.324500f, 0.432250f), Point(0.375500f, 0.457750f), Point(0.375500f, 0.579350f), Point(0.324500f, 0.553850f))
    val outline = listOf(Point(0.500000f, 0.220000f), Point(0.800000f, 0.370000f), Point(0.800000f, 0.690000f), Point(0.500000f, 0.840000f), Point(0.200000f, 0.690000f), Point(0.200000f, 0.370000f))

    fun project(u: Float, v: Float, z: Float = 0f): Point = Point(
        0.5f + 0.3f * u + (-0.3f) * v,
        0.22f + 0.15f * u + 0.15f * v - 0.32f * z,
    )

    fun lids(closed: Float): Pair<List<Point>, List<Point>> {
        val angle = (1f - closed.coerceIn(0f, 1f)) * 1.832595715f
        val depth = cos(angle) * .5f
        val lift = sin(angle) * .5f
        val rear = listOf(project(0f, 0f), project(1f, 0f), project(1f, depth, lift), project(0f, depth, lift))
        val front = listOf(project(0f, 1f), project(1f, 1f), project(1f, 1f-depth, lift), project(0f, 1f-depth, lift))
        return rear to front
    }
}
